import {
  EXPOSURES,
  HOST_TYPES,
  PORT_PROTOCOLS,
  SERVICE_STATUSES,
  type Host,
  type PathMapping,
  type Service,
  type StackMapExport,
} from './types'
import { migrateLegacyPaths } from './pathMappings'

export const CURRENT_SCHEMA_VERSION = 3

const isString = (value: unknown): value is string => typeof value === 'string'
const isNonEmptyString = (value: unknown): value is string =>
  isString(value) && value.trim().length > 0
const isOptionalString = (value: unknown): value is string | undefined =>
  value === undefined || isString(value)
const isIsoTimestamp = (value: unknown): value is string =>
  isString(value) &&
  !Number.isNaN(Date.parse(value)) &&
  new Date(value).toISOString() === value

function hasExactKeys(value: Record<string, unknown>, keys: string[]) {
  return Object.keys(value).every((key) => keys.includes(key))
}

function isPathMapping(value: unknown): value is PathMapping {
  if (!value || typeof value !== 'object') return false
  const path = value as Record<string, unknown>
  return (
    hasExactKeys(path, ['id', 'hostPath', 'containerPath', 'purpose', 'readOnly']) &&
    isNonEmptyString(path.id) &&
    isString(path.hostPath) &&
    isString(path.containerPath) &&
    isString(path.purpose) &&
    typeof path.readOnly === 'boolean'
  )
}

function isServiceShape(value: unknown, schemaVersion: 1 | 2 | 3): boolean {
  if (!value || typeof value !== 'object') return false
  const service = value as Record<string, unknown>
  const keys = [
    'id',
    'name',
    ...(schemaVersion >= 2
      ? ['containerName', 'dockerImage', 'description', 'applicationUrl']
      : []),
    'status',
    'hostId',
    'internalUrl',
    'ports',
    ...(schemaVersion < 3 ? ['configPath', 'dataPath'] : ['paths']),
    'network',
    'exposure',
    'dependencyIds',
    'notes',
    'createdAt',
    'updatedAt',
  ]

  return (
    hasExactKeys(service, keys) &&
    isNonEmptyString(service.id) &&
    isNonEmptyString(service.name) &&
    (schemaVersion < 2 ||
      (isString(service.containerName) &&
        isString(service.dockerImage) &&
        isString(service.description) &&
        isString(service.applicationUrl))) &&
    SERVICE_STATUSES.includes(service.status as Service['status']) &&
    isOptionalString(service.hostId) &&
    isString(service.internalUrl) &&
    Array.isArray(service.ports) &&
    service.ports.every((port) => {
      if (!port || typeof port !== 'object') return false
      const item = port as Record<string, unknown>
      return (
        hasExactKeys(item, ['hostPort', 'containerPort', 'protocol', 'description']) &&
        (item.hostPort === undefined ||
          (Number.isInteger(item.hostPort) && Number(item.hostPort) > 0 && Number(item.hostPort) <= 65535)) &&
        (item.containerPort === undefined ||
          (Number.isInteger(item.containerPort) &&
            Number(item.containerPort) > 0 &&
            Number(item.containerPort) <= 65535)) &&
        (item.hostPort !== undefined || item.containerPort !== undefined) &&
        PORT_PROTOCOLS.includes(item.protocol as Service['ports'][number]['protocol']) &&
        isString(item.description)
      )
    }) &&
    (schemaVersion < 3
      ? isString(service.configPath) && isString(service.dataPath)
      : Array.isArray(service.paths) && service.paths.every(isPathMapping)) &&
    isString(service.network) &&
    EXPOSURES.includes(service.exposure as Service['exposure']) &&
    Array.isArray(service.dependencyIds) &&
    service.dependencyIds.every(isString) &&
    new Set(service.dependencyIds).size === service.dependencyIds.length &&
    !service.dependencyIds.includes(service.id) &&
    isString(service.notes) &&
    isIsoTimestamp(service.createdAt) &&
    isIsoTimestamp(service.updatedAt)
  )
}

export function isService(value: unknown): value is Service {
  if (!isServiceShape(value, 3)) return false
  const paths = (value as Service).paths
  return new Set(paths.map((path) => path.id)).size === paths.length
}

export function isHost(value: unknown): value is Host {
  if (!value || typeof value !== 'object') return false
  const host = value as Record<string, unknown>
  return (
    hasExactKeys(host, [
      'id',
      'name',
      'type',
      'ipAddress',
      'operatingSystem',
      'notes',
      'createdAt',
      'updatedAt',
    ]) &&
    isNonEmptyString(host.id) &&
    isNonEmptyString(host.name) &&
    HOST_TYPES.includes(host.type as Host['type']) &&
    isString(host.ipAddress) &&
    isString(host.operatingSystem) &&
    isString(host.notes) &&
    isIsoTimestamp(host.createdAt) &&
    isIsoTimestamp(host.updatedAt)
  )
}

export function validateImport(value: unknown): StackMapExport {
  if (!value || typeof value !== 'object') {
    throw new Error('The selected file does not contain a StackMap export.')
  }

  const data = value as Record<string, unknown>
  if (![1, 2, CURRENT_SCHEMA_VERSION].includes(data.schemaVersion as number)) {
    throw new Error(
      `Unsupported schema version. Expected version 1, 2, or ${CURRENT_SCHEMA_VERSION}.`,
    )
  }
  if (!isString(data.exportedAt) || Number.isNaN(Date.parse(data.exportedAt))) {
    throw new Error('The export timestamp is missing or invalid.')
  }
  const schemaVersion = data.schemaVersion as 1 | 2 | 3
  if (!Array.isArray(data.services)) {
    throw new Error('One or more service records are invalid.')
  }
  if (
    schemaVersion === 3 &&
    data.services.some((service) => {
      if (!service || typeof service !== 'object') return false
      const paths = (service as Record<string, unknown>).paths
      return !Array.isArray(paths) || !paths.every(isPathMapping)
    })
  ) {
    throw new Error('One or more service records contain malformed path mappings.')
  }
  if (!data.services.every((service) => isServiceShape(service, schemaVersion))) {
    throw new Error('One or more service records are invalid.')
  }
  if (!Array.isArray(data.hosts) || !data.hosts.every(isHost)) {
    throw new Error('One or more host records are invalid.')
  }

  const hostIds = new Set(data.hosts.map((host) => host.id))
  const serviceIds = new Set(data.services.map((service) => service.id))
  if (hostIds.size !== data.hosts.length || serviceIds.size !== data.services.length) {
    throw new Error('The import contains duplicate record IDs.')
  }
  if (
    schemaVersion === 3 &&
    data.services.some((service) => {
      const paths = (service as Service).paths
      return new Set(paths.map((path) => path.id)).size !== paths.length
    })
  ) {
    throw new Error('A service contains duplicate path-mapping IDs.')
  }
  if (data.services.some((service) => service.hostId && !hostIds.has(service.hostId))) {
    throw new Error('A service references a host that is not included in the import.')
  }
  if (
    data.services.some((service) =>
      service.dependencyIds.some((id: string) => !serviceIds.has(id)),
    )
  ) {
    throw new Error('A service dependency is not included in the import.')
  }

  return {
    schemaVersion: CURRENT_SCHEMA_VERSION,
    exportedAt: data.exportedAt,
    services: data.services.map((service) => {
      const source = service as Record<string, unknown>
      if (schemaVersion === 3) {
        const current = source as unknown as Service
        return { ...current, paths: current.paths.map((path) => ({ ...path })) }
      }
      const { configPath, dataPath, ...withoutLegacyPaths } = source
      return {
        ...withoutLegacyPaths,
        ...(schemaVersion === 1
          ? { containerName: '', dockerImage: '', description: '', applicationUrl: '' }
          : {}),
        paths: migrateLegacyPaths(String(source.id), {
          configPath: String(configPath ?? ''),
          dataPath: String(dataPath ?? ''),
        }),
      } as unknown as Service
    }),
    hosts: data.hosts.map((host) => ({ ...host })),
  }
}
DATABASE
import Dexie, { type EntityTable } from 'dexie'
import { CURRENT_SCHEMA_VERSION } from '../domain/schema'
import { migrateLegacyPaths } from '../domain/pathMappings'
import type { Host, Service, StackMapData } from '../domain/types'

interface StackMapMetadata {
  key: 'schemaVersion'
  value: number
}

export class StackMapDatabase extends Dexie {
  services!: EntityTable<Service, 'id'>
  hosts!: EntityTable<Host, 'id'>
  metadata!: EntityTable<StackMapMetadata, 'key'>

  constructor(name = 'stackmap') {
    super(name)
    this.version(1).stores({
      services: 'id, name, status, hostId, network, exposure, updatedAt',
      hosts: 'id, name, type, updatedAt',
    })
    this.version(2)
      .stores({
        services: 'id, name, status, hostId, network, exposure, updatedAt',
        hosts: 'id, name, type, updatedAt',
        metadata: 'key',
      })
      .upgrade(async (transaction) => {
        await transaction
          .table<StackMapMetadata, 'key'>('metadata')
          .put({ key: 'schemaVersion', value: CURRENT_SCHEMA_VERSION })
      })
    this.version(3)
      .stores({
        services: 'id, name, status, hostId, network, exposure, updatedAt',
        hosts: 'id, name, type, updatedAt',
        metadata: 'key',
      })
      .upgrade(async (transaction) => {
        await transaction
          .table<Service, 'id'>('services')
          .toCollection()
          .modify((service) => {
            service.containerName ??= ''
            service.dockerImage ??= ''
            service.description ??= ''
            service.applicationUrl ??= ''
          })
        await transaction
          .table<StackMapMetadata, 'key'>('metadata')
          .put({ key: 'schemaVersion', value: CURRENT_SCHEMA_VERSION })
      })
    this.version(4)
      .stores({
        services: 'id, name, status, hostId, network, exposure, updatedAt',
        hosts: 'id, name, type, updatedAt',
        metadata: 'key',
      })
      .upgrade(async (transaction) => {
        await transaction
          .table<Record<string, unknown>, 'id'>('services')
          .toCollection()
          .modify((service) => {
            const configPath = typeof service.configPath === 'string' ? service.configPath : ''
            const dataPath = typeof service.dataPath === 'string' ? service.dataPath : ''
            service.paths = migrateLegacyPaths(String(service.id), { configPath, dataPath })
            delete service.configPath
            delete service.dataPath
          })
        await transaction
          .table<StackMapMetadata, 'key'>('metadata')
          .put({ key: 'schemaVersion', value: CURRENT_SCHEMA_VERSION })
      })
  }
}

export interface StackMapRepository {
  getAll(): Promise<StackMapData>
  putService(service: Service): Promise<void>
  deleteService(id: string): Promise<void>
  putHost(host: Host): Promise<void>
  deleteHost(id: string): Promise<void>
  replaceAll(data: StackMapData): Promise<void>
  getSchemaVersion(): Promise<number>
}

export class DexieStackMapRepository implements StackMapRepository {
  constructor(private readonly database = new StackMapDatabase()) {}

  async getAll(): Promise<StackMapData> {
    await this.getSchemaVersion()
    const [services, hosts] = await Promise.all([
      this.database.services.toArray(),
      this.database.hosts.toArray(),
    ])
    return { services, hosts }
  }

  async putService(service: Service) {
    if (service.hostId && !(await this.database.hosts.get(service.hostId))) {
      throw new Error('The selected host no longer exists.')
    }
    const dependencyCount = await this.database.services
      .where('id')
      .anyOf(service.dependencyIds)
      .count()
    if (dependencyCount !== new Set(service.dependencyIds).size) {
      throw new Error('One or more selected dependencies no longer exist.')
    }
    await this.database.services.put(service)
  }

  async deleteService(id: string) {
    await this.database.transaction('rw', this.database.services, async () => {
      await this.database.services.delete(id)
      const dependents = await this.database.services
        .filter((service) => service.dependencyIds.includes(id))
        .toArray()
      await this.database.services.bulkPut(
        dependents.map((service) => ({
          ...service,
          dependencyIds: service.dependencyIds.filter((dependencyId) => dependencyId !== id),
          updatedAt: new Date().toISOString(),
        })),
      )
    })
  }

  async putHost(host: Host) {
    await this.database.hosts.put(host)
  }

  async deleteHost(id: string) {
    const referenceCount = await this.database.services.where('hostId').equals(id).count()
    if (referenceCount > 0) {
      throw new Error('This host is assigned to one or more services.')
    }
    await this.database.hosts.delete(id)
  }

  async replaceAll(data: StackMapData) {
    await this.database.transaction(
      'rw',
      this.database.services,
      this.database.hosts,
      async () => {
        await Promise.all([this.database.services.clear(), this.database.hosts.clear()])
        await this.database.services.bulkAdd(data.services)
        await this.database.hosts.bulkAdd(data.hosts)
      },
    )
  }

  async getSchemaVersion() {
    const metadata = await this.database.metadata.get('schemaVersion')
    if (!metadata) {
      await this.database.metadata.put({
        key: 'schemaVersion',
        value: CURRENT_SCHEMA_VERSION,
      })
      return CURRENT_SCHEMA_VERSION
    }
    return metadata.value
  }
}

export const repository = new DexieStackMapRepository()
SERVICE_UTILS
import type { Host, PathMapping, Service, ServiceFilters, ServicePort } from './types'

export function missingServiceFields(service: Service): string[] {
  const missing: string[] = []
  if (!service.hostId) missing.push('host')
  if (!service.internalUrl.trim()) missing.push('internal URL')
  if (!service.ports.length) missing.push('ports')
  if (!hasConfigurationPath(service.paths)) missing.push('configuration path')
  if (!service.network.trim()) missing.push('network')
  if (service.exposure === 'unknown') missing.push('exposure')
  return missing
}

export type PathStyle = 'absolute' | 'relative'

export interface PathWarnings {
  incompleteMappingIds: string[]
  mixedHostPaths: boolean
  mixedContainerPaths: boolean
  missingConfiguration: boolean
}

export function isAbsolutePath(path: string): boolean {
  const value = path.trim()
  return value.startsWith('/') || /^[A-Za-z]:[\\/]/.test(value) || value.startsWith('\\\\')
}

function hasMixedStyles(paths: string[]): boolean {
  const styles = new Set<PathStyle>(
    paths.filter((path) => path.trim()).map((path) => (isAbsolutePath(path) ? 'absolute' : 'relative')),
  )
  return styles.size > 1
}

export function hasConfigurationPath(paths: PathMapping[]): boolean {
  return paths.some((path) => path.purpose.toLowerCase().includes('config'))
}

export function getPathWarnings(paths: PathMapping[]): PathWarnings {
  return {
    incompleteMappingIds: paths
      .filter((path) => Boolean(path.hostPath.trim()) !== Boolean(path.containerPath.trim()))
      .map((path) => path.id),
    mixedHostPaths: hasMixedStyles(paths.map((path) => path.hostPath)),
    mixedContainerPaths: hasMixedStyles(paths.map((path) => path.containerPath)),
    missingConfiguration: !hasConfigurationPath(paths),
  }
}

function protocolsOverlap(left: ServicePort['protocol'], right: ServicePort['protocol']) {
  if (left === 'unknown' || right === 'unknown') return left === right
  return left === 'both' || right === 'both' || left === right
}

export function duplicatePortServiceIds(services: Service[]): Set<string> {
  const duplicateIds = new Set<string>()
  const assignments = services.flatMap((service) =>
    service.hostId
      ? service.ports
          .filter((port) => port.hostPort !== undefined)
          .map((port, portIndex) => ({ service, port, portIndex }))
      : [],
  )

  assignments.forEach((assignment, index) => {
    assignments.slice(index + 1).forEach((candidate) => {
      if (
        assignment.service.hostId === candidate.service.hostId &&
        assignment.port.hostPort === candidate.port.hostPort &&
        protocolsOverlap(assignment.port.protocol, candidate.port.protocol) &&
        (assignment.service.id !== candidate.service.id ||
          assignment.portIndex !== candidate.portIndex)
      ) {
        duplicateIds.add(assignment.service.id)
        duplicateIds.add(candidate.service.id)
      }
    })
  })
  return duplicateIds
}

export function duplicateContainerNameServiceIds(services: Service[]): Set<string> {
  const duplicateIds = new Set<string>()
  const assignments = new Map<string, string[]>()

  services.forEach((service) => {
    const containerName = service.containerName.trim().toLowerCase()
    if (!service.hostId || !containerName || service.status === 'retired') return
    const key = `${service.hostId}\u0000${containerName}`
    assignments.set(key, [...(assignments.get(key) ?? []), service.id])
  })

  assignments.forEach((ids) => {
    if (ids.length > 1) ids.forEach((id) => duplicateIds.add(id))
  })

  return duplicateIds
}

export function filterServices(
  services: Service[],
  hosts: Host[],
  filters: ServiceFilters,
): Service[] {
  const hostNames = new Map(hosts.map((host) => [host.id, host.name.toLowerCase()]))
  const query = filters.query.trim().toLowerCase()

  return services.filter((service) => {
    const searchable = [
      service.name,
      service.containerName,
      service.dockerImage,
      service.description,
      service.applicationUrl,
      service.internalUrl,
      ...service.paths.flatMap((path) => [path.hostPath, path.containerPath, path.purpose]),
      service.network,
      service.notes,
      service.hostId ? hostNames.get(service.hostId) : '',
      ...service.ports.flatMap((port) => [
        port.hostPort?.toString(),
        port.containerPort?.toString(),
        port.description,
      ]),
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase()

    return (
      (!query || searchable.includes(query)) &&
      (filters.status === 'all' || service.status === filters.status) &&
      (filters.hostId === 'all' || service.hostId === filters.hostId) &&
      (filters.network === 'all' || service.network === filters.network) &&
      (filters.exposure === 'all' || service.exposure === filters.exposure)
    )
  })
}

export function createService(name: string): Service {
  const timestamp = new Date().toISOString()
  return {
    id: crypto.randomUUID(),
    name: name.trim(),
    containerName: '',
    dockerImage: '',
    description: '',
    applicationUrl: '',
    status: 'active',
    internalUrl: '',
    ports: [],
    paths: [],
    network: '',
    exposure: 'unknown',
    dependencyIds: [],
    notes: '',
    createdAt: timestamp,
    updatedAt: timestamp,
  }
}

